mapper.select:
SELECT c.id AS id, c.name AS customerName, c.contact_person AS contactPerson, c.contact_phone AS contactPhone, c.email AS email, c.address AS address, c.industry AS industry, c.customer_level AS customerLevel, c.status AS status, c.remark AS remark, c.organization_id AS organizationId, c.create_time AS createTime FROM ad_customer c WHERE c.organization_id = #{request.organizationId} AND c.deleted = 0
AND c.customer_level = #{request.customerLevel}
AND c.status = #{request.status}
AND (c.name LIKE CONCAT('%', #{request.keyword}, '%') OR c.contact_person LIKE CONCAT('%', #{request.keyword}, '%') OR c.contact_phone LIKE CONCAT('%', #{request.keyword}, '%'))
